/**
 * The vendored, third-party skills we ship.
 *
 * Each module in this directory is generated by `scripts/vendor-skills.mjs` from an
 * upstream MIT-licensed repository, and carries the commit it came from. Nothing here is
 * hand-edited: `node scripts/vendor-skills.mjs` refreshes, `--check` reports drift.
 *
 * WHY VENDOR RATHER THAN FETCH AT RUNTIME
 * A production agent must not depend on GitHub being up, must not pay a network round trip
 * to read instructions, and must be reproducible â€” the same deploy must answer the same way
 * next month. Vendoring gives all three, at the cost of a manual refresh, which is a
 * deliberate price: the content changes only when we choose.
 *
 * ATTRIBUTION IS PART OF THE CONTRACT
 * `attribution` on each skill names the repo, the path, the commit and the licence. The
 * gate (`npm run verify:vendor-skills`) fails if it is missing or if the licence is not on
 * the allow-list. Removing an attribution to make a test pass is not a fix.
 */

import { skill as bannerDesign } from './banner-design';
import { skill as metaAdsCreative } from './meta-ads-creative';
import { skill as scrollCraft } from './scroll-craft';
import { skill as uiUxProMax } from './ui-ux-pro-max';
import { skill as videoShotcraft } from './video-shotcraft';

export interface VendoredSkill {
  name: string;
  description: string;
  /**
   * What we vendored it FOR.
   *
   * Upstream descriptions are written for a human browsing a repository, not for routing:
   * scroll-craft's never mentions a landing page, so a keyword router could not find it for
   * the one job it is best at. This line is ours and is what makes it findable.
   */
  useFor: string;
  content: string;
  attribution: {
    repo: string;
    path: string;
    commit: string;
    licence: string;
    url: string;
  };
}

/** Licences we are allowed to ship. Anything else must be judged by a human, not a regex. */
export const ALLOWED_LICENCES = ['MIT', 'Apache-2.0', 'BSD-2-Clause', 'BSD-3-Clause', 'ISC'] as const;

export const VENDORED_SKILLS: readonly VendoredSkill[] = [
  metaAdsCreative as VendoredSkill,
  scrollCraft as VendoredSkill,
  uiUxProMax as VendoredSkill,
  bannerDesign as VendoredSkill,
  videoShotcraft as VendoredSkill,
];

/** By name, for `get_skill`. */
export function vendoredSkill(name: string): VendoredSkill | null {
  const wanted = String(name ?? '').trim().toLowerCase();
  return VENDORED_SKILLS.find((skill) => skill.name.toLowerCase() === wanted) ?? null;
}

/**
 * The catalogue entries the prompt and `list_skills` show.
 *
 * `useFor` is folded into the description HERE rather than in the skill body, so the router
 * and the prompt see a line that names the job, while the skill's own content stays exactly
 * as upstream wrote it.
 */
export function vendoredSkillCatalogue(): { name: string; description: string }[] {
  return VENDORED_SKILLS.map((skill) => ({
    name: skill.name,
    description: skill.useFor ? `${skill.description} Use for: ${skill.useFor}` : skill.description,
  }));
}

/** Where a vendored skill came from, as one line for the log or an admin view. */
export function attributionLine(skill: VendoredSkill): string {
  const { repo, licence, commit } = skill.attribution;
  return `${skill.name} â€” ${repo} (${licence}, ${commit.slice(0, 8)})`;
}
